package bo.com.ganadero.animales.infrastructure; import bo.com.ganadero.animales.domain.*; import bo.com.ganadero.shared.db.Rows; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.stereotype.Repository; import java.util.*;
@Repository class JdbcRazaRepository implements RazaRepository {private final JdbcClient jdbc;JdbcRazaRepository(JdbcClient j){jdbc=j;}public List<Raza> findActive(UUID e){return jdbc.sql("select * from raza where activo order by nombre").query((r,n)->new Raza(Rows.uuid(r,"id"),null,r.getString("codigo"),r.getString("nombre"),r.getString("especie"),r.getString("descripcion"),r.getBoolean("activo"))).list();}public Optional<Raza> findById(UUID id,UUID e){return jdbc.sql("select * from raza where id=:id and activo").param("id",id.toString()).query((r,n)->new Raza(Rows.uuid(r,"id"),null,r.getString("codigo"),r.getString("nombre"),r.getString("especie"),r.getString("descripcion"),r.getBoolean("activo"))).optional();}}
